<?php require_once 'config.php';require_login();$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT a.*,c.title course_title,c.trainer_id FROM assessments a JOIN courses c ON c.id=a.course_id WHERE a.id=?');$s->execute([$id]);$assessment=$s->fetch();if(!$assessment){http_response_code(404);exit('Assessment not found.');}$u=current_user();$isOwner=$u['role']==='admin'||($u['role']==='trainer'&&(int)$assessment['trainer_id']===(int)$u['id']);$s=db()->prepare('SELECT id FROM enrollments WHERE user_id=? AND course_id=?');$s->execute([$u['id'],$assessment['course_id']]);$isEnrolled=(bool)$s->fetch();if(!$isOwner&&!$isEnrolled){flash('Enroll in the course before attempting this assessment.','error');redirect('course.php?id='.$assessment['course_id']);}$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($isOwner&&$action==='add_question'){$q=trim($_POST['question_text']??'');$a=trim($_POST['option_a']??'');$b=trim($_POST['option_b']??'');$c=trim($_POST['option_c']??'');$d=trim($_POST['option_d']??'');$correct=$_POST['correct_option']??'';if($q&&$a&&$b&&$c&&$d&&in_array($correct,['A','B','C','D'],true)){$s=db()->prepare('INSERT INTO questions(assessment_id,question_text,option_a,option_b,option_c,option_d,correct_option) VALUES(?,?,?,?,?,?,?)');$s->execute([$id,$q,$a,$b,$c,$d,$correct]);$s=db()->prepare('UPDATE assessments SET question_count=(SELECT COUNT(*) FROM questions WHERE assessment_id=?) WHERE id=?');$s->execute([$id,$id]);flash('Question added.');redirect('assessment.php?id='.$id);}else $error='Complete the question and all four answer options.';}elseif(!$isOwner&&$action==='submit_assessment'){$s=db()->prepare('SELECT * FROM questions WHERE assessment_id=? ORDER BY id');$s->execute([$id]);$questions=$s->fetchAll();if(!$questions){$error='This assessment does not have any questions yet.';}else{$score=0;$answers=[];foreach($questions as $q){$answer=$_POST['q_'.$q['id']]??'';$answers[$q['id']]=$answer;if($answer===$q['correct_option'])$score++;}$percentage=(int)round(($score/count($questions))*100);$s=db()->prepare('INSERT INTO assessment_attempts(user_id,assessment_id,score,total_questions,percentage,answers_json) VALUES(?,?,?,?,?,?)');$s->execute([$u['id'],$id,$score,count($questions),$percentage,json_encode($answers)]);flash("Assessment submitted: $score out of ".count($questions)." correct ($percentage%).");redirect('assessment.php?id='.$id);}}}
$s=db()->prepare('SELECT * FROM questions WHERE assessment_id=? ORDER BY id');$s->execute([$id]);$questions=$s->fetchAll();$pageTitle=$assessment['title'];$s=db()->prepare('SELECT * FROM assessment_attempts WHERE assessment_id=? AND user_id=? ORDER BY attempted_at DESC');$s->execute([$id,$u['id']]);$attempts=$s->fetchAll();require 'includes/header.php'; ?>
<section class="page-heading compact-heading"><a class="back-link" href="course.php?id=<?= (int)$assessment['course_id'] ?>">← <?= e($assessment['course_title']) ?></a><span class="eyebrow">ASSESSMENT</span><h1><?= e($assessment['title']) ?></h1><p><?= count($questions) ?> questions · <?= (int)$assessment['total_marks'] ?> total marks</p></section><section class="section narrow-section"><?php if($error): ?><div class="alert error"><?= e($error) ?></div><?php endif; ?><?php if($isOwner): ?><div class="panel"><h2>Add a multiple-choice question</h2><p class="muted">Correct answers are used for automatic scoring.</p><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="add_question"><label>Question<textarea name="question_text" rows="3" required placeholder="Enter the question..."></textarea></label><div class="form-grid"><label>Option A<input name="option_a" required></label><label>Option B<input name="option_b" required></label><label>Option C<input name="option_c" required></label><label>Option D<input name="option_d" required></label></div><label>Correct answer<select name="correct_option"><option>A</option><option>B</option><option>C</option><option>D</option></select></label><button class="btn btn-primary">Add question →</button></form></div><?php endif; ?><?php if(!$isOwner): ?><?php if($attempts): ?><div class="panel"><h2>Your previous attempts</h2><?php foreach($attempts as $a): ?><div class="attempt-row"><span><?= e(date('d M Y, H:i',strtotime($a['attempted_at']))) ?></span><b><?= (int)$a['score'] ?>/<?= (int)$a['total_questions'] ?> · <?= (int)$a['percentage'] ?>%</b></div><?php endforeach; ?></div><?php endif; ?><?php if($questions): ?><form method="post" class="panel assessment-form" data-confirm="Submit your answers now?"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="submit_assessment"><?php foreach($questions as $i=>$q): ?><fieldset class="question-block"><legend><?= ($i+1).'. '.e($q['question_text']) ?></legend><?php foreach(['A'=>'option_a','B'=>'option_b','C'=>'option_c','D'=>'option_d'] as $letter=>$col): ?><label class="answer-option"><input type="radio" name="q_<?= (int)$q['id'] ?>" value="<?= $letter ?>" required><span><b><?= $letter ?>.</b> <?= e($q[$col]) ?></span></label><?php endforeach; ?></fieldset><?php endforeach; ?><button class="btn btn-primary btn-full">Submit assessment →</button></form><?php else: ?><div class="empty-state"><span>✎</span><h3>Questions are being prepared</h3><p>Your trainer hasn't added questions to this assessment yet. Check back soon.</p></div><?php endif; ?><?php endif; ?></section><?php require 'includes/footer.php'; ?>
